skill_power_formula.pseudocode:
effective_level = query_skill(skill) + query_temp('apply/attack' or 'apply/defense');
if (effective_level == 0) return combat_exp / 2;
power = (effective_level ^ 3) / 3;
power = power * sen / max_sen;  // 道心修正
power += combat_exp;
return power;

dodge_formula.pseudocode:
ap = skill_power(attacker, attack_skill, ATTACK);
dp = skill_power(victim, 'dodge', DEFENSE);
if (victim.is_busy()) dp /= 3;  // 忙碌时闪避大幅降低
mod_val = dp * (100 + action['dodge']) / 100;  // 技能闪避修正
if (random(ap + dp) < mod_val) → 闪避成功，damage = RESULT_DODGE;

parry_formula.pseudocode:
if (victim有法器) pp = skill_power(victim, 'parry', DEFENSE);
else if (attacker无法器) pp = skill_power(victim, 'unarmed', DEFENSE);
else pp = 0;  // 空手对法器无法格挡
if (attacker无法器 && victim有法器) pp *= 2;  // 法器对空手格挡翻倍
if (victim.is_busy()) pp /= 3;
mod_val = pp * (100 + action['parry']) / 100;
if (random(ap + pp) < mod_val) → 格挡成功，damage = RESULT_PARRY;

damage_formula.pseudocode:
// 基础伤害
base_damage = query_temp('apply/damage');  // 法器基础伤害
damage = (base_damage + random(base_damage)) / 2;  // 50%-100%法器伤害
if (action['damage']) damage += action['damage'] * damage / 100;  // 技能伤害倍率

// 伤害加成
damage_bonus = query_str();  // 体格加成

// 内功加成
if (force_factor && force > force_factor) {
    force_bonus = force_skill->hit_ob(me, victim, damage_bonus, force_factor);
    damage_bonus += force_bonus;
}
if (action['force']) damage_bonus += action['force'] * damage_bonus / 100;

// 武功技能加成
martial_bonus = martial_skill->hit_ob(me, victim, damage_bonus);
damage_bonus += martial_bonus;

// 法器特效加成
if (weapon) weapon_bonus = weapon->hit_ob(me, victim, damage_bonus);
else monster_bonus = me->hit_ob(me, victim, damage_bonus) * 3/4;

// 最终伤害
damage += (damage_bonus + random(damage_bonus)) / 2;
if (damage < 0) damage = 0;

// 战斗经验防御修正
defense_factor = victim.combat_exp;
while (random(defense_factor) > attacker.combat_exp) {
    damage -= damage / 3;  // 每次减1/3
    defense_factor /= 2;
}

armor_and_wound_formula.pseudocode:
damage = victim->receive_damage('kee', damage, me);
if ((me.is_killing(victim) || weapon) && random(damage) > armor) {
    wound = damage - armor;
    victim->receive_wound('kee', wound, me);
}
